select
  id, study_id, patient_id, exam_no, test_no, create_time, update_time, result_time, abnormal_indicator_high, abnormal_indicator_low, total_bile_acid, white_ball_ratio, ast_alt_ratio, indirect_bilirubin, alanine_aminotransferase, aspartate_aminotransferase, total_protein, albumin, globulin, total_bilirubin, direct_bilirubin
from td_liver_function_items


        and id = #{id}


        and study_id = #{studyId}


        and patient_id = #{patientId}


        and exam_no = #{examNo}


        and test_no = #{testNo}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and result_time = #{resultTime}


        and abnormal_indicator_high = #{abnormalIndicatorHigh}


        and abnormal_indicator_low = #{abnormalIndicatorLow}


        and total_bile_acid = #{totalBileAcid}


        and white_ball_ratio = #{whiteBallRatio}


        and ast_alt_ratio = #{astAltRatio}


        and indirect_bilirubin = #{indirectBilirubin}


        and alanine_aminotransferase = #{alanineAminotransferase}


        and aspartate_aminotransferase = #{aspartateAminotransferase}


        and total_protein = #{totalProtein}


        and albumin = #{albumin}


        and globulin = #{globulin}


        and total_bilirubin = #{totalBilirubin}


        and direct_bilirubin = #{directBilirubin}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from td_liver_function_items


        and id = #{id}


        and study_id = #{studyId}


        and patient_id = #{patientId}


        and exam_no = #{examNo}


